{
  "item_id": "PRISMA_2020_1",
  "elements": [
    {
      "element_id": "prisma_2020_1_e1",
      "status": "PARTIAL",
      "chunk_id": "text_2",
      "quote": "Identifying existing approaches used to evaluate the sustainability of evidence-based interventions in healthcare: an integrative review",
      "reason": "The title identifies the report as a review ('an integrative review'), but does not explicitly identify it as a 'systematic review'. The methods (text_8, text_3) describe a systematic, PRISMA-guided process, but the title itself uses 'integrative review'."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Identifying existing approaches used to evaluate the sustainability of evidence-based interventions in healthcare",
      "reason": "The title clearly conveys the main objective/review question: identifying approaches to evaluate sustainability of evidence-based interventions (intervention/exposure) in healthcare (population/context)."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "an integrative review",
      "reason": "The title provides supplementary methodological information by specifying the review type/study design used ('integrative review')."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "There is limited evidence to evaluate the sustainability of evidence-based interventions (EBIs) for healthcare improvement.",
      "reason": "The Background/abstract describes the current state of knowledge (limited evidence, existing syntheses such as Lennox et al. cited in the Discussion) and identifies the uncertainty that it is unclear which approaches are most effective for evaluating sustainability."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "implementation, which often requires substantial resources, is meaningless without long-term sustainability efforts",
      "reason": "The importance and need for the review are explained: sustainability evaluation is essential, and the review 'offers methodological recommendations for sustainability evaluation research and highlights the importance in understanding mechanisms of sustainability to advance the field.'"
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_20",
      "quote": "A focus on evaluation is what differentiates this review from recent syntheses published on approaches to sustainability research.",
      "reason": "Similar prior syntheses (e.g., Lennox et al. [6], a recent scoping review [8]) are identified and cited, and the need for the current review is explained by its distinct focus on evaluation approaches."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of approaches used to evaluate sustainability of EBIs, not a review of intervention effects, so describing a mechanism of action of an intervention does not apply."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review examines theoretical approaches to sustainability evaluation rather than assessing a complex intervention's effects, so a logic model of intervention components and outcomes is not a requirement of this review."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "The aim of this integrative review was to identify and synthesize approaches that have been used to evaluate the sustainability of EBIs in healthcare. We aimed to enhance our understanding of sustainability definitions, research designs, data collection methods, timing, measures, and sustainability outcomes used for sustainability evaluation studies.",
      "reason": "The review objectives are explicitly stated in a dedicated Aim section, clearly articulating the primary aim and secondary objectives."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_8",
      "quote": "Integrative reviews can include diverse data sources and do not restrict the type of study design.",
      "reason": "This is an integrative review of approaches to evaluating sustainability, not a review of intervention effects; no planned effectiveness comparisons are reported, so PICO does not apply."
    }
  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "table_0",
      "quote": "Articles were included if they: • Were published in a peer-review journal • Were primary research • Had explicit research design and data collection methods • Had an explicit theoretical approach for sustainability ... • Were within a healthcare setting • Evaluated the sustainability of an EBI",
      "reason": "Table 1 specifies study characteristics for eligibility including design (primary research, explicit design/methods), setting (healthcare, with definition in footnote g), and the requirement of an independent sustainability evaluation component; text_7 adds that studies had to have an independent sustainability evaluation component."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "table_0",
      "quote": "Articles were included if they: • Were published in a peer-review journal ... Articles were excluded if they: • Were secondary research • Were gray literature",
      "reason": "Publication status (peer-reviewed, not gray literature) is specified, but no dissemination year or language restriction appears in the eligibility criteria; the English-language restriction is only mentioned retrospectively in the Limitations (text_21)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": "table_0",
      "quote": "Did not evaluate the sustainability of an EBI or QI intervention using a defined approach or, • Did not evaluate sustainability using a clear research design and method",
      "reason": "The exclusion criteria do not distinguish exclusion because sustainability outcomes were not measured from exclusion because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "MISSING",
      "chunk_id": "text_10",
      "quote": "The two reviewers independently extracted the following variables: (1) study design, (2) evaluation type (independent versus composite), (3) sustainability definition and terms used, (4) type and name of theoretical approach...",
      "reason": "Data extraction variables are listed, but the manuscript does not specify groups used in each synthesis or link them to comparisons defined in the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PARTIAL",
      "chunk_id": "text_3",
      "quote": "Included studies were not restricted by research design; and had to evaluate the sustainability of an EBI in a healthcare context.",
      "reason": "A rationale is implied for not restricting study design (integrative review methodology, text_8) and the healthcare setting restriction is defined (footnote g), but explicit rationales for other notable restrictions (e.g., peer-reviewed only, English language) are not provided in the methods."
    }
  ],
  "confidence": 88
}

